export const navigationStateToSearchParams = (state: NavigateStoreState): URLSearchParams => {
  const params = new URLSearchParams();

  if (state.selectedGraphPartId) params.set(SELECTED_GRAPH_PART_PARAM, state.selectedGraphPartId);
  if (state.viewingExploreDiagram) params.set(EXPLORE_DIAGRAM_PARAM, "true");
  if (state.viewingCriteriaTable) params.set(CRITERIA_TABLE_PARAM, "true");
  if (state.activeTableProblemId) params.set(TABLE_PROBLEM_PARAM, state.activeTableProblemId);
  if (state.viewingClaimTree) params.set(CLAIM_TREE_PARAM, "true");
  if (state.activeClaimTreeId) params.set(CLAIM_TREE_ID_PARAM, state.activeClaimTreeId);

  return params;
};
```

