export const useSolutionTotal = (solution: Node, problem: Node) => {
  const edgeScores = useTopicStore((state) => {
    const topicGraph = { nodes: state.nodes, edges: state.edges };
    const criteria = children(problem, topicGraph).filter((node) => node.type === "criterion");

    const edges = compact(
      criteria.map((criterion) => {
        // could maybe save some work here by sharing edges between solutions, but not worried about perf here
        return edges(criterion, state.edges).find((edge) => edge.target === solution.id);
      })
    );

    return edges.map((edge) => {
      return { criterionId: edge.source, edgeId: edge.id };
    });
  });

  const graphPartIds = [...edgeScores.flatMap(({ criterionId, edgeId }) => [criterionId, edgeId])];
  const scoresByGraphPart = useDisplayScoresByGraphPart(graphPartIds);

  return sum(edgeScores.map(({ criterionId, edgeId }) => {
    const edgeScore = scoresByGraphPart[edgeId];
    const criterionScore = scoresByGraphPart[criterionId];
    if (edgeScore === undefined || criterionScore === undefined) {
      throwError("missing score", { edgeScore, criterionScore, edgeId, criterionId });
    }

    return (getNumericScore(edgeScore) - 5) * (getNumericScore(criterionScore) - 1);
  }));
};
```

