        return { criterion, edge };
      })
    );

    return solutionEdges;
  }, shallow);

  const scoresByGraphPart = useDisplayScoresByGraphPart(
    edgeScores.flatMap(({ criterion, edge }) => [criterion.id, edge.id])
  );

  return sum(
    edgeScores.map(({ criterion, edge }) => {
      const edgeScore = scoresByGraphPart[edge.id];
      const criterionScore = scoresByGraphPart[criterion.id];

      if (edgeScore === undefined || criterionScore === undefined) {
        throwError("Edge or criterion score could not be found", { edgeScore, criterionScore });
      }

      return (getNumericScore(edgeScore) - 5) * (getNumericScore(criterionScore) - 1);
    })
  );
};
```

