```ts
export const useSolutionTotal = (solution: Node, problem: Node) => {
  const edgeScores = useTopicStore(
    (state) => {
      const topicGraph = { nodes: state.nodes, edges: state.edges };
      const criteria = children(problem, topicGraph).filter((node) => node.type === "criterion");

      return compact(
        criteria.map((criterion) => {
          // could maybe share edges between solutions, but not worried about perf here as the table can't have that many columns
          const edge = edges(criterion, state.edges).find((edge) => edge.target === solution.id);
          if (!edge) return undefined;

          return { criterion, edge };
        })
      );
    },
    shallow
  );

  const scoresByGraphPart = useDisplayScoresByGraphPart(
    edgeScores.flatMap(({ criterion, edge }) => [criterion.id, edge.id])
  );

  return sum(
    edgeScores.map(({ criterion, edge }) => {
      const edgeScore = scoresByGraphPart[edge.id];
      const criterionScore = scoresByGraphPart[criterion.id];
      if (edgeScore === undefined || criterionScore === undefined) {
        throwError("score missing for solution total", { edgeScore, criterionScore });
      }

      return (getNumericScore(edgeScore) - 5) * (getNumericScore(criterionScore) - 1);
    })
  );
};
