export const useUserScores = (graphPartId: string, perspectives: string[]) => {
  return useTopicStore(
    (state) => {
      const userScores: [string, Score][] = perspectives.map((perspective) => [
        perspective,
        get(state.userScores, [perspective, graphPartId], "-"),
      ]);

      return Object.fromEntries(userScores);
    },
    shallow
  );
};

export const useScoringUsernames = () => {
  return useTopicStore((state) => {
    return Object.keys(state.userScores);
  });
};

// the solution total is a sum of how well the solution embodies each criterion, weighted by the
// importance of the criterion
export const useSolutionTotal = (solution: Node, problem: Node) => {
  const solutionEdges = useTopicStore((state) => {
    const topicGraph = { nodes: state.nodes, edges: state.edges };
    const criteria = children(problem, topicGraph).filter((node) => node.type === "criterion");

    // could maybe share edges between solutions, but not worried about perf here as there won't be
    // that many solutions to score against
    return compact(
      criteria.map((criterion) => {
        const edge = edges(criterion, state.edges).find((edge) => edge.target === solution.id);
        if (!edge) return undefined;

        return edge;
      })
    );
  }, shallow);

  const scoresByGraphPart = useDisplayScoresByGraphPart(
    solutionEdges.flatMap((edge) => [edge.source, edge.id])
  );

  // edge scores signal how well the solution embodies the criterion, shifted so that a score of 5
  // (implicitly), i.e. "not applicable", results in no contribution
  // criterion scores signal the importance of the criterion, shifted so that it acts as a weight
  return sum(
    solutionEdges.map((edge) => {
      const edgeScore = scoresByGraphPart[edge.id];
      const criterionScore = scoresByGraphPart[edge.source];
      if (edgeScore === undefined || criterionScore === undefined) {
        throwError("Edge or criterion score could not be found", { edgeScore, criterionScore });
      }

      return (getNumericScore(edgeScore) - 5) * (getNumericScore(criterionScore) - 1);
    })
  );
};

// the criterion total is a sum of how well each solution embodies the criterion, weighted by the
// importance of the criterion
export const useCriterionTotal = (criterion: Node, problem: Node) => {
  const criterionEdges = useTopicStore((state) => {
    const topicGraph = { nodes: state.nodes, edges: state.edges };
    const solutions = children(problem, topicGraph).filter((node) => node.type === "solution");

    return compact(
      solutions.map((solution) => {
        const edge = edges(criterion, state.edges).find((edge) => edge.target === solution.id);
        if (!edge) return undefined;

        return edge;
      })
    );
  }, shallow);

  const scoresByGraphPart = useDisplayScoresByGraphPart([
    criterion.id,
    ...criterionEdges.map((edge) => edge.id),
  ]);
  const criterionScore = scoresByGraphPart[criterion.id];

  return sum(
    criterionEdges.map((edge) => {
      const edgeScore = scoresByGraphPart[edge.id];
      if (edgeScore === undefined || criterionScore === undefined) {
        throwError("Edge or criterion score could not be found", { edgeScore, criterionScore });
      }

      return (getNumericScore(edgeScore) - 5) * (getNumericScore(criterionScore) - 1);
    })
  );
};

