import { Info } from "@mui/icons-material";
import {
  Box,
  Button,
  IconButton,
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableRow,
  Tooltip,
  Typography,
} from "@mui/material";
import { useState } from "react";

// note: MUI tooltips with interactive content are finicky, so the tooltip is toggleable by clicking
// the info icon rather than relying on hover
export const TotalsHeaderCell = () => {
  const [isInfoTooltipOpen, setIsInfoTooltipOpen] = useState<boolean>(false);
  const [showExactDetails, setShowExactDetails] = useState<boolean>(false);

  return (
    <Box
      sx={{
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        height: "100%",
      }}
    >
      <Typography variant="body2">Solution Totals</Typography>
      <Tooltip
        arrow
        open={isInfoTooltipOpen}
        title={showExactDetails ? <ExactDetails /> : <Description />}
        onOpen={() => setIsInfoTooltipOpen(true)}
        onClose={() => setIsInfoTooltipOpen(false)}
      >
        <IconButton
          color="info"
          aria-label="Solution totals info"
          sx={{ cursor: "default" }}
          onClick={() => setIsInfoTooltipOpen((prev) => !prev)}
        >
          <Info />
        </IconButton>
      </Tooltip>
    </Box>
  );
};

const Description = () => {
  const [showExactDetails, setShowExactDetails] = useState<boolean>(false);

  return (
    <Box onClick={(event) => event.stopPropagation()}>
      <Typography variant="body2">
        The Solution Total indicates how well each solution satisfies the criteria for the problem,
        weighted by how important each criterion is.
      </Typography>
      <Button size="small" onClick={() => setShowExactDetails(true)}>
        Show exact details
      </Button>
      {showExactDetails && <ExactDetails />}
    </Box>
  );
};

// breakdown of how the total is calculated, per the criteria table enhancement
const ExactDetails = () => {
  return (
    <Box onClick={(event) => event.stopPropagation()}>
      <Typography variant="body2">
        For each criterion connected to the problem:
        <br />
        - take the edge score (how well the solution embodies the criterion, on a scale of 1 to 9)
        and subtract 5, so it's shifted from -4 to +4 (low means it doesn't embody the criterion,
        high means it does)
        <br />
        - take the criterion score (how important the criterion is, on a scale of 1 to 9) and
        subtract 1, so it acts as a weight from 0 to 8
        <br />- multiply the two adjusted scores together
        <br />
        The Solution Total is the sum of these products across all criteria.
      </Typography>
      <Box marginTop={1}>
        <Table size="small">
          <TableHead>
            <TableRow>
              <TableCell>Criterion</TableCell>
              <TableCell>Edge score</TableCell>
              <TableCell>Importance</TableCell>
              <TableCell>Contribution</TableCell>
            </TableRow>
          </TableHead>
          <TableBody>
            <TableRow>
              <TableCell>Criterion A</TableCell>
              <TableCell>8</TableCell>
              <TableCell>7</TableCell>
              <TableCell>(8 - 5) × (7 - 1) = 18</TableCell>
            </TableRow>
            <TableRow>
              <TableCell>Criterion B</TableCell>
              <TableCell>4</TableCell>
              <TableCell>8</TableCell>
              <TableCell>(4 - 5) × (8 - 1) = -7</TableCell>
            </TableRow>
            <TableRow>
              <TableCell>Total</TableCell>
              <TableCell colSpan={2} />
              <TableCell>11</TableCell>
            </TableRow>
          </TableBody>
        </Table>
      </Box>
    </Box>
  );
};

