import { Global } from "@emotion/react";
import { Cancel, PivotTableChart } from "@mui/icons-material";
import { Button, IconButton, Tooltip } from "@mui/material";
import {
  type MRT_ColumnDef,
  MRT_FullScreenToggleButton,
  MRT_ShowHideColumnsButton,
  type MRT_TableInstance,
  MRT_ToggleFiltersButton,
  MRT_ToggleGlobalFilterButton,
  MaterialReactTable,
} from "material-react-table";
import React, { useState } from "react";

import { errorWithData, throwError } from "../../../../common/errorHandling";
import { Loading } from "../../../common/components/Loading/Loading";
import { useSessionUser } from "../../../common/hooks";
import { closeTable } from "../../../view/navigateStore";
import { useCriterionSolutionEdges, useNode, useNodeChildren } from "../../store/nodeHooks";
import { useUserCanEditTopicData } from "../../store/userHooks";
import { getConnectingEdge } from "../../utils/edge";
import { Edge, Node } from "../../utils/graph";
import { EdgeCell } from "../CriteriaTable/EdgeCell";
import { NodeCell } from "../CriteriaTable/NodeCell";
import { AddNodeButton } from "../Node/AddNodeButton";
import { CriterionTotalCell } from "./CriterionTotalCell";
import { SolutionTotalCell } from "./SolutionTotalCell";
import { tableStyles } from "./CriteriaTable.styles";
import { TotalsHeaderCell } from "./TotalsHeaderCell";

// a node header cell (i.e. problem, criterion, or solution), or the totals header cell
type HeaderCell = { node: Node } | { title: string };

// an edge cell between a row & column node, or the totals cell for that row
type Cell = { edge: Edge } | { total: { rowNode: Node; problem: Node } };

interface RowData {
  rowHeaderLabel: string;
  rowHeader: HeaderCell;
  cells: Cell[];
}

const buildNodeHeader = (node: Node): HeaderCell => {
  return { node };
};

const buildEdgeCell = (edge: Edge): Cell => {
  return { edge };
};

const buildTotalsHeader = (): HeaderCell => {
  return { title: "Solution Totals" };
};

const buildSolutionTotalCell = (solution: Node, problem: Node): Cell => {
  return { total: { rowNode: solution, problem } };
};

const buildCriterionTotalCell = (criterion: Node, problem: Node): Cell => {
  return { total: { rowNode: criterion, problem } };
};

const buildRowTotalCell = (rowNode: Node, problemNode: Node): Cell => {
  return rowNode.type === "solution"
    ? buildSolutionTotalCell(rowNode, problemNode)
    : buildCriterionTotalCell(rowNode, problemNode);
};

// returns structure:
// [
//   [problemNode, columnNode1, columnNode2, ..., totalsHeader],
//   [rowNode1, edgeCell, edgeCell, ..., rowTotalCell],
//   ...
// ]
// where the first array is the header row and the rest are body rows.
//
// `columnNodes` become the table columns and `rowNodes` become the rows, so transposing is done by
// swapping the columns & rows at the call site.
const buildTableCells = (
  problemNode: Node,
  columnNodes: Node[],
  rowNodes: Node[],
  edges: Edge[]
): [[HeaderCell, ...HeaderCell[]], ...[HeaderCell, ...Cell[]][]] => {
  const headerCells: [HeaderCell, ...HeaderCell[]] = [
    buildNodeHeader(problemNode),
    ...columnNodes.map((columnNode) => buildNodeHeader(columnNode)),
    buildTotalsHeader(),
  ];

  const bodyCells: [HeaderCell, ...Cell[]][] = rowNodes.map((rowNode) => {
    const edgeCells: Cell[] = columnNodes.map((columnNode) => {
      const edge = getConnectingEdge(rowNode.id, columnNode.id, edges);
      if (!edge) {
        throw errorWithData(`No edge found between ${rowNode.id} and ${columnNode.id}`, edges);
      }

      return buildEdgeCell(edge);
    });

    const row: [HeaderCell, ...Cell[]] = [
      buildNodeHeader(rowNode),
      ...edgeCells,
      buildRowTotalCell(rowNode, problemNode),
    ];

    return row;
  });

  return [headerCells, ...bodyCells];
};

const isNodeHeader = (cell: HeaderCell): cell is { node: Node } => "node" in cell;

interface FilterDetails {
  rowTitles: string[];
  rowType: "criteria" | "solutions";
}

const buildColumns = (
  problemNode: Node,
  headerCells: [HeaderCell, ...HeaderCell[]],
  filterDetails: FilterDetails
): MRT_ColumnDef<RowData>[] => {
  const [problemHeader, ...columnHeaders] = headerCells;
  if (!isNodeHeader(problemHeader)) throwError("expected a node header cell", problemHeader);

  return [
    {
      accessorKey: "rowHeaderLabel", // this determines how cols should sort/filter
      header: filterDetails.rowType,
      Header: <NodeCell node={problemNode} />,
      filterVariant: "multi-select",
      filterSelectOptions: filterDetails.rowTitles,
      enableHiding: false,
      Cell: ({ row }) => {
        if (!isNodeHeader(row.original.rowHeader)) {
          throwError("expected a node header cell", row.original.rowHeader);
        }
        return <NodeCell node={row.original.rowHeader.node} />;
      },
    },
    ...columnHeaders.map(
      (columnHeader, columnIndex) =>
        ({
          // Don't yet know what we'd want to sort/filter by for edges, so we're setting id instead
          // of accessorKey
          id: columnHeader.type === "node" ? columnHeader.node.id : "totals",
          header: columnHeader.type === "node" ? columnHeader.node.data.label : "Solution Totals",
          Header:
            columnHeader.type === "node" ? (
              <NodeCell node={columnHeader.node} />
            ) : (
              <TotalsHeaderCell />
            ),
          ...(columnHeader.type === "node"
            ? {
                enableColumnFilter: false,
                Cell: ({ row }: { row: MRT_Row<RowData> }) => {
                  const cell = row.original.cells[columnIndex];
                  if (cell === undefined || !("edge" in cell)) {
                    throwError("expected an edge cell", cell);
                  }
                  return <EdgeCell edge={cell.edge} />;
                },
              }
            : {
                enableColumnFilter: false,
                enableHiding: false, // computed summary, doesn't make sense to hide
                Cell: ({ row }: { row: MRT_Row<RowData> }) => {
                  const cell = row.original.cells[columnIndex];
                  if (cell === undefined || !("total" in cell)) {
                    throwError("expected a total cell", cell);
                  }

                  const { rowNode, problem } = cell.total;
                  return rowNode.type === "solution" ? (
                    <SolutionTotalCell solution={rowNode} problem={problem} />
                  ) : (
                    <CriterionTotalCell criterion={rowNode} problem={problem} />
                  );
                },
              }) as MRT_ColumnDef<RowData>
        } as MRT_ColumnDef<RowData>)
    ),
  ];
};

interface Props {
  problemNodeId: string;
}

export const CriteriaTable = ({ problemNodeId }: Props) => {
  const { sessionUser } = useSessionUser();
  const userCanEditTopicData = useUserCanEditTopicData(sessionUser?.username);
  const [useSolutionsForColumns, setUseSolutionsForColumns] = useState<boolean>(true);
  const problemNode = useNode(problemNodeId);
  const nodeChildren = useNodeChildren(problemNodeId);
  const criterionSolutionEdges = useCriterionSolutionEdges(problemNodeId);

  if (!problemNode) return <Loading />;

  const criteria = nodeChildren.filter((node) => node.type === "criterion");
  const solutions = nodeChildren.filter((node) => node.type === "solution");

  const rowNodes = useSolutionsForColumns ? criteria : solutions;
  const columnNodes = useSolutionsForColumns ? solutions : criteria;

  const filterDetails = {
    rowTitles: rowNodes.map((node) => node.data.label),
    // eslint-disable-next-line @typescript-eslint/no-unnecessary-type-assertion -- hmm casting is necessary for some reason
    rowType: (useSolutionsForColumns ? "criteria" : "solutions") as "criteria" | "solutions",
  };

  const [headerCells, ...bodyCells] = buildTableCells(
    problemNode,
    columnNodes,
    rowNodes,
    criterionSolutionEdges
  );

  const rowData: RowData[] = bodyCells.map(([rowHeader, ...cells]) => {
    if (!isNodeHeader(rowHeader)) throwError("expected a node header cell", rowHeader);

    return { rowHeaderLabel: rowHeader.node.data.label, rowHeader, cells };
  });

  const columnData = buildColumns(problemNode, headerCells, filterDetails);

  const ToolBarActions = (table: MRT_TableInstance<RowData>) => {
    return (
      <>
        <MRT_ToggleGlobalFilterButton table={table} />
        <MRT_ToggleFiltersButton table={table} />
        <MRT_ShowHideColumnsButton table={table} />

        {userCanEditTopicData && (
          <>
            <AddNodeButton
              fromPartId={problemNodeId}
              as="child"
              toNodeType="solution"
              relation={{ child: "solution", name: "addresses", parent: "problem" }}
            />

            <AddNodeButton
              fromPartId={problemNodeId}
              as="child"
              toNodeType="criterion"
              relation={{ child: "criterion", name: "criterionFor", parent: "problem" }}
            />
          </>
        )}

        <Tooltip title="Transpose Table">
          <Button
            size="small"
            variant="contained"
            color="neutral"
            onClick={() => setUseSolutionsForColumns(!useSolutionsForColumns)}
          >
            <PivotTableChart />
          </Button>
        </Tooltip>

        <MRT_FullScreenToggleButton table={table} />
        <Tooltip title="Close">
          <IconButton onClick={() => closeTable()} color="primary">
            <Cancel />
          </IconButton>
        </Tooltip>
      </>
    );
  };

  return (
    <>
      <Global styles={tableStyles} />

      <MaterialReactTable
        columns={columnData}
        data={rowData}
        enableColumnActions={false}
        enablePagination={false}
        enableBottomToolbar={false}
        renderToolbarInternalActions={({ table }) => ToolBarActions(table)}
        enableSorting={false}
        enableStickyHeader={true}
        // not very well documented in the library, but this drop zone takes up space for unknown reasons.
        positionToolbarDropZone="none"
        muiTablePaperProps={{
          className: "criteria-table-paper",
        }}
        initialState={{
          columnPinning: { left: ["rowHeaderLabel"], right: ["totals"] },
          // columnOrder is defaulted to all cols, but then we'd have to maintain columnOrder when new cols are added
          // defaulting this to empty should be fine until we want column reordering, then I think we'll have to maintain that
          // manually, in order to have new columns included (new columns i.e. from transposing)
          columnOrder: [],
        }}
      />
    </>
  );
};

