const buildColumns = (
  problemNode: Node,
  headerCells: [HeaderCell, ...HeaderCell[]],
  filterDetails: FilterDetails
): MRT_ColumnDef<RowData>[] => {
  const [problemHeader, ...columnHeaders] = headerCells;
  if (!isNodeHeader(problemHeader)) throwError("expected a node header cell", problemHeader);

  return [
    {
      accessorKey: "rowHeaderLabel", // this determines how cols should sort/filter
      header: filterDetails.rowType,
      Header: <NodeCell node={problemNode} />,
      filterVariant: "multi-select",
      filterSelectOptions: filterDetails.rowTitles,
      enableHiding: false,
      Cell: ({ row }) => {
        if (!isNodeHeader(row.original.rowHeader)) {
          throwError("expected a node header cell", row.original.rowHeader);
        }
        return <NodeCell node={row.original.rowHeader.node} />;
      },
    },
    ...columnHeaders.map(
      (columnHeader, columnIndex) =>
        ({
          // Don't yet know what we'd want to sort/filter by for edges, so we're setting id instead
          // of accessorKey
          id: columnHeader.type === "node" ? columnHeader.node.id : "totals",
          header: columnHeader.type === "node" ? columnHeader.node.data.label : "Solution Totals",
          Header:
            columnHeader.type === "node" ? (
              <NodeCell node={columnHeader.node} />
            ) : (
              <TotalsHeaderCell />
            ),
          ...(columnHeader.type === "node"
            ? {
                enableColumnFilter: false,
                Cell: ({ row }: { row: MRT_Row<RowData> }) => {
                  const cell = row.original.cells[columnIndex];
                  if (cell === undefined || !("edge" in cell)) {
                    throwError("expected an edge cell", cell);
                  }
                  return <EdgeCell edge={cell.edge} />;
                },
              }
            : {
                enableColumnFilter: false,
                enableHiding: false, // computed summary, doesn't make sense to hide
                Cell: ({ row }: { row: MRT_Row<RowData> }) => {
                  const cell = row.original.cells[columnIndex];
                  if (cell === undefined || !("total" in cell)) {
                    throwError("expected a total cell", cell);
                  }

                  const { rowNode, problem } = cell.total;
                  return rowNode.type === "solution" ? (
                    <SolutionTotalCell solution={rowNode} problem={problem} />
                  ) : (
                    <CriterionTotalCell criterion={rowNode} problem={problem} />
                  );
                },
              }) as MRT_ColumnDef<RowData>
        } as MRT_ColumnDef<RowData>)
    ),
  ];
};

